using Microsoft.EntityFrameworkCore;

sealed class PortalUser
{
    public int UserId { get; set; }
    public required string UserName { get; set; }
    public required string UserEmail { get; set; }
    public required string UserPasswordHash { get; set; }
    public required string UserRole { get; set; }
    public bool IsActive { get; set; }
    public DateTime CreatedAtUtc { get; set; }
    public DateTime UpdatedAtUtc { get; set; }
    public ICollection<Pop> CreatedPops { get; } = new List<Pop>();
    public ICollection<Pop> UpdatedPops { get; } = new List<Pop>();
}

sealed class Department { public int DepartmentId { get; set; } public required string DepartmentName { get; set; } public required string DepartmentCode { get; set; } public bool IsActive { get; set; } public DateTime CreatedAtUtc { get; set; } public DateTime UpdatedAtUtc { get; set; } }
sealed class Pop { public int PopId { get; set; } public int CreatedBy { get; set; } public int? UpdatedBy { get; set; } public required string PopTitle { get; set; } public string? PopDescription { get; set; } public string? PopFilePath { get; set; } public string? PopVersion { get; set; } public required string PopStatus { get; set; } public DateTime CreatedAtUtc { get; set; } public DateTime UpdatedAtUtc { get; set; } public PortalUser? Creator { get; set; } public PortalUser? Updater { get; set; } }
sealed class UserDepartment { public int UserDepartmentId { get; set; } public int UserId { get; set; } public int DepartmentId { get; set; } public required string AccessType { get; set; } public DateTime ValidFromAtUtc { get; set; } public DateTime? ExpiresAtUtc { get; set; } public DateTime? RevokedAtUtc { get; set; } public PortalUser? User { get; set; } public Department? Department { get; set; } }
sealed class PortalLink { public int LinkId { get; set; } public required string LinkPath { get; set; } public DateTime CreatedAtUtc { get; set; } public DateTime UpdatedAtUtc { get; set; } }
sealed class Feedback { public int FeedbackId { get; set; } public int UserId { get; set; } public int? PopId { get; set; } public int? AnsweredBy { get; set; } public required string FeedbackDescription { get; set; } public required string FeedbackStatus { get; set; } public string? FeedbackAnswer { get; set; } public DateTime CreatedAtUtc { get; set; } public DateTime? AnsweredAtUtc { get; set; } public PortalUser? User { get; set; } public Pop? Pop { get; set; } public PortalUser? AnsweredByUser { get; set; } }
sealed class Checklist { public int ChecklistId { get; set; } public int PopId { get; set; } public int UserId { get; set; } public string? ChecklistDescription { get; set; } public DateTime CreatedAtUtc { get; set; } public DateTime? CompletedAtUtc { get; set; } public Pop? Pop { get; set; } public PortalUser? User { get; set; } }
sealed class StandardCheck { public int StandardCheckId { get; set; } public int PopId { get; set; } public required string CheckText { get; set; } public int CheckOrder { get; set; } public Pop? Pop { get; set; } }
sealed class ChecklistItemResult { public int ChecklistItemResultId { get; set; } public int ChecklistId { get; set; } public int StandardCheckId { get; set; } public bool IsChecked { get; set; } public Checklist? Checklist { get; set; } public StandardCheck? StandardCheck { get; set; } }
sealed class PopLink { public int PopLinkId { get; set; } public int PopId { get; set; } public int LinkId { get; set; } public Pop? Pop { get; set; } public PortalLink? Link { get; set; } }
sealed class PopDepartment { public int PopDepartmentId { get; set; } public int PopId { get; set; } public int DepartmentId { get; set; } public required string AccessType { get; set; } public Pop? Pop { get; set; } public Department? Department { get; set; } }

static class PortalSchemaConfiguration
{
    public static void ConfigurePortalSchema(this ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<PortalUser>(entity =>
        {
            entity.ToTable("User"); entity.HasKey(x => x.UserId);
            entity.Property(x => x.UserId).HasColumnName("user_id");
            entity.Property(x => x.UserName).HasColumnName("user_name").HasMaxLength(120).IsRequired();
            entity.Property(x => x.UserEmail).HasColumnName("user_email").HasMaxLength(256).IsRequired();
            entity.Property(x => x.UserPasswordHash).HasColumnName("user_password_hash").HasMaxLength(512).IsRequired();
            entity.Property(x => x.UserRole).HasColumnName("user_role").HasMaxLength(20).IsRequired();
            entity.Property(x => x.IsActive).HasColumnName("is_active"); entity.Property(x => x.CreatedAtUtc).HasColumnName("created_at_utc"); entity.Property(x => x.UpdatedAtUtc).HasColumnName("updated_at_utc");
            entity.HasIndex(x => x.UserEmail).IsUnique().HasDatabaseName("IX_User_user_email");
        });
        modelBuilder.Entity<Department>(entity => { entity.ToTable("Department"); entity.HasKey(x => x.DepartmentId); entity.Property(x => x.DepartmentId).HasColumnName("department_id"); entity.Property(x => x.DepartmentName).HasColumnName("department_name").HasMaxLength(120).IsRequired(); entity.Property(x => x.DepartmentCode).HasColumnName("department_code").HasMaxLength(30).IsRequired(); entity.Property(x => x.IsActive).HasColumnName("is_active"); entity.Property(x => x.CreatedAtUtc).HasColumnName("created_at_utc"); entity.Property(x => x.UpdatedAtUtc).HasColumnName("updated_at_utc"); entity.HasIndex(x => x.DepartmentCode).IsUnique().HasDatabaseName("IX_Department_department_code"); });
        modelBuilder.Entity<Pop>(entity => { entity.ToTable("Pop"); entity.HasKey(x => x.PopId); entity.Property(x => x.PopId).HasColumnName("pop_id"); entity.Property(x => x.CreatedBy).HasColumnName("created_by"); entity.Property(x => x.UpdatedBy).HasColumnName("updated_by"); entity.Property(x => x.PopTitle).HasColumnName("pop_title").HasMaxLength(200).IsRequired(); entity.Property(x => x.PopDescription).HasColumnName("pop_description"); entity.Property(x => x.PopFilePath).HasColumnName("pop_file_path").HasMaxLength(500); entity.Property(x => x.PopVersion).HasColumnName("pop_version").HasMaxLength(50); entity.Property(x => x.PopStatus).HasColumnName("pop_status").HasMaxLength(20).IsRequired(); entity.Property(x => x.CreatedAtUtc).HasColumnName("created_at_utc"); entity.Property(x => x.UpdatedAtUtc).HasColumnName("updated_at_utc"); entity.HasOne(x => x.Creator).WithMany(x => x.CreatedPops).HasForeignKey(x => x.CreatedBy).OnDelete(DeleteBehavior.Restrict); entity.HasOne(x => x.Updater).WithMany(x => x.UpdatedPops).HasForeignKey(x => x.UpdatedBy).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<UserDepartment>(entity => { entity.ToTable("UserDepartment"); entity.HasKey(x => x.UserDepartmentId); entity.Property(x => x.UserDepartmentId).HasColumnName("user_department_id"); entity.Property(x => x.UserId).HasColumnName("user_id"); entity.Property(x => x.DepartmentId).HasColumnName("department_id"); entity.Property(x => x.AccessType).HasColumnName("access_type").HasMaxLength(30).IsRequired(); entity.Property(x => x.ValidFromAtUtc).HasColumnName("valid_from_at_utc"); entity.Property(x => x.ExpiresAtUtc).HasColumnName("expires_at_utc"); entity.Property(x => x.RevokedAtUtc).HasColumnName("revoked_at_utc"); entity.HasOne(x => x.User).WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Cascade); entity.HasOne(x => x.Department).WithMany().HasForeignKey(x => x.DepartmentId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.UserId, x.DepartmentId }).IsUnique(); });
        modelBuilder.Entity<PortalLink>(entity => { entity.ToTable("Link"); entity.HasKey(x => x.LinkId); entity.Property(x => x.LinkId).HasColumnName("link_id"); entity.Property(x => x.LinkPath).HasColumnName("link_path").HasMaxLength(1000).IsRequired(); entity.Property(x => x.CreatedAtUtc).HasColumnName("created_at_utc"); entity.Property(x => x.UpdatedAtUtc).HasColumnName("updated_at_utc"); });
        modelBuilder.Entity<Feedback>(entity => { entity.ToTable("Feedback"); entity.HasKey(x => x.FeedbackId); entity.Property(x => x.FeedbackId).HasColumnName("feedback_id"); entity.Property(x => x.UserId).HasColumnName("user_id"); entity.Property(x => x.PopId).HasColumnName("pop_id"); entity.Property(x => x.AnsweredBy).HasColumnName("answered_by"); entity.Property(x => x.FeedbackDescription).HasColumnName("feedback_description").IsRequired(); entity.Property(x => x.FeedbackStatus).HasColumnName("feedback_status").HasMaxLength(20).IsRequired(); entity.Property(x => x.FeedbackAnswer).HasColumnName("feedback_answer"); entity.Property(x => x.CreatedAtUtc).HasColumnName("created_at_utc"); entity.Property(x => x.AnsweredAtUtc).HasColumnName("answered_at_utc"); entity.HasOne(x => x.User).WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Restrict); entity.HasOne(x => x.Pop).WithMany().HasForeignKey(x => x.PopId).OnDelete(DeleteBehavior.SetNull); entity.HasOne(x => x.AnsweredByUser).WithMany().HasForeignKey(x => x.AnsweredBy).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<Checklist>(entity => { entity.ToTable("Checklist"); entity.HasKey(x => x.ChecklistId); entity.Property(x => x.ChecklistId).HasColumnName("checklist_id"); entity.Property(x => x.PopId).HasColumnName("pop_id"); entity.Property(x => x.UserId).HasColumnName("user_id"); entity.Property(x => x.ChecklistDescription).HasColumnName("checklist_description"); entity.Property(x => x.CreatedAtUtc).HasColumnName("created_at_utc"); entity.Property(x => x.CompletedAtUtc).HasColumnName("completed_at_utc"); entity.HasOne(x => x.Pop).WithMany().HasForeignKey(x => x.PopId).OnDelete(DeleteBehavior.Cascade); entity.HasOne(x => x.User).WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<StandardCheck>(entity => { entity.ToTable("StandardCheck"); entity.HasKey(x => x.StandardCheckId); entity.Property(x => x.StandardCheckId).HasColumnName("standard_check_id"); entity.Property(x => x.PopId).HasColumnName("pop_id"); entity.Property(x => x.CheckText).HasColumnName("check_text").IsRequired(); entity.Property(x => x.CheckOrder).HasColumnName("check_order"); entity.HasOne(x => x.Pop).WithMany().HasForeignKey(x => x.PopId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.PopId, x.CheckOrder }).IsUnique(); });
        modelBuilder.Entity<ChecklistItemResult>(entity => { entity.ToTable("ChecklistItemResult"); entity.HasKey(x => x.ChecklistItemResultId); entity.Property(x => x.ChecklistItemResultId).HasColumnName("checklist_item_result_id"); entity.Property(x => x.ChecklistId).HasColumnName("checklist_id"); entity.Property(x => x.StandardCheckId).HasColumnName("standard_check_id"); entity.Property(x => x.IsChecked).HasColumnName("is_checked"); entity.HasOne(x => x.Checklist).WithMany().HasForeignKey(x => x.ChecklistId).OnDelete(DeleteBehavior.Cascade); entity.HasOne(x => x.StandardCheck).WithMany().HasForeignKey(x => x.StandardCheckId).OnDelete(DeleteBehavior.Restrict); entity.HasIndex(x => new { x.ChecklistId, x.StandardCheckId }).IsUnique(); });
        modelBuilder.Entity<PopLink>(entity => { entity.ToTable("PopLink"); entity.HasKey(x => x.PopLinkId); entity.Property(x => x.PopLinkId).HasColumnName("pop_link_id"); entity.Property(x => x.PopId).HasColumnName("pop_id"); entity.Property(x => x.LinkId).HasColumnName("link_id"); entity.HasOne(x => x.Pop).WithMany().HasForeignKey(x => x.PopId).OnDelete(DeleteBehavior.Cascade); entity.HasOne(x => x.Link).WithMany().HasForeignKey(x => x.LinkId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.PopId, x.LinkId }).IsUnique(); });
        modelBuilder.Entity<PopDepartment>(entity => { entity.ToTable("PopDepartment"); entity.HasKey(x => x.PopDepartmentId); entity.Property(x => x.PopDepartmentId).HasColumnName("pop_department_id"); entity.Property(x => x.PopId).HasColumnName("pop_id"); entity.Property(x => x.DepartmentId).HasColumnName("department_id"); entity.Property(x => x.AccessType).HasColumnName("access_type").HasMaxLength(30).IsRequired(); entity.HasOne(x => x.Pop).WithMany().HasForeignKey(x => x.PopId).OnDelete(DeleteBehavior.Cascade); entity.HasOne(x => x.Department).WithMany().HasForeignKey(x => x.DepartmentId).OnDelete(DeleteBehavior.Cascade); entity.HasIndex(x => new { x.PopId, x.DepartmentId }).IsUnique(); });
    }
}
